/**
 * 蒙面英雄的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _slotsNode:null,//slots游戏节点
        isBigStoreToFreeGame: false,//是开启单页玫瑰商店进的免费游戏
        isSmallStoreToFreeGame: false,//是开启玫瑰商店进的免费游戏

    },

    //set nodepopui的脚本
    SetPopNodeScript(scp) {
        this._popupScp = scp
    },

    //get nodepopui的脚本
    GetPopNodeScript(scp) {
        return this._popupScp
    },

    //set slotsNode
    SetSlotsNode(scp) {
        this._slotsNode = scp
    },

    //get slotsNode
    GetSlotsNode(scp) {
        return this._slotsNode
    },

    // 设置游戏的Wheel脚本
    SetWheelScript(scp) {
        this._wheelScp = scp
    },

    // 获得游戏的Wheel脚本
    GetWheelScript() {
        return this._wheelScp
    },

    // 设置玫瑰商店的脚本
    SetStoreScript(scp) {
        this._storeScp = scp
    },

    // 获得玫瑰商店的脚本
    GetStoreScript() {
        return this._storeScp
    },

    // 设置当前是否开启单页玫瑰商店进的免费游戏
    SetBigStoreToFreeGame(scp) {
        this.isBigStoreToFreeGame = scp
    },

    // 获得当前是否开启单页玫瑰商店进的免费游戏
    GetBigStoreToFreeGame() {
        return this.isBigStoreToFreeGame
    },

    // 设置当前是否开启玫瑰商店进的免费游戏
    SetSmallStoreToFreeGame(scp) {
        this.isSmallStoreToFreeGame = scp
    },

    // 获得当前是否开启玫瑰商店进的免费游戏
    GetSmallStoreToFreeGame() {
        return this.isSmallStoreToFreeGame
    },

    //解锁五种bonus游戏的押注index
    SetJackpotUnlock(JackpotUnlock) {
        this.JackpotUnlock = JackpotUnlock
    },

    GetJackpotUnlock() {
        return this.JackpotUnlock
    },

    //将押注等级转换成押注额度
    //押注等级是从1开始，和服务端保持一致
    IdxToBet(idx) {
        return this._deskInfo.mults[idx]
    },
});

