
/**蒙面英雄玫瑰商店
 * 
*/
let BigDuel_Tools = require('./BigDuel_Tools')

cc.Class({
    extends: cc.Component,

    properties: {
        //cc
        chooseSpf1: cc.SpriteFrame,//下方choose
        chooseSpf2: cc.SpriteFrame,

        itemOpenSpf: cc.SpriteFrame,//袋子打开
        itemCloseSpf: cc.SpriteFrame,//袋子关闭
        itemGraySpf: cc.SpriteFrame,//袋子灰色


        _beginFlyItem: cc.node,//中的repick多选择一次item
        _flyLizi: cc.node,//飞翔粒子
        _cannotOpenTip: cc.node,//袋子打不开tip

        _upSpine: cc.node,//上方spine node
        //属性
        _roseStore: null,//rosestore消息字段
        _page: 1,//当前页数 总页数5
        _unlockPage: 1,//解锁页数
        _repick: false,//是否处于repick

    },

    Init() {
        this._flyLizi = cc.find("bg/flyLizi", this.node)
        this._cannotOpenTip = cc.find("bg/cannotOpenTip", this.node)
        this._upSpine = cc.find("bg/shangdiandakai", this.node)

        //左滑动
        Global.btnClickEvent(cc.find("bg/leftBtn", this.node), function () {
            let spineNode = cc.find("bg/leftBtn/jiantou", this.node)
            spineNode.active = true
            BigDuel_Tools.playSpineAni(spineNode, "animation1", false)
            BigDuel_Tools.spineEndFunc(spineNode, () => {
                spineNode.active = false
            })
            this.movePage(1)
        }, this)
        //右滑动
        Global.btnClickEvent(cc.find("bg/rightBtn", this.node), function () {
            let spineNode = cc.find("bg/rightBtn/jiantou", this.node)
            spineNode.active = true
            BigDuel_Tools.playSpineAni(spineNode, "animation1", false)
            BigDuel_Tools.spineEndFunc(spineNode, () => {
                spineNode.active = false
            })
            this.movePage(2)
        }, this)
        //关闭按钮
        Global.btnClickEvent(cc.find("bg/btnClose", this.node), function () {
            Global.SlotsSoundMgr.playEffect("btn_click");
            this.closeRoseStore();
            cc.vv.gameData.GetSlotsScript().CanDoNextRound();
        }, this)
    },

    onLoad() {
        let self = this
        this.initUi()
        this.updateUi()
        let pageView = cc.find("bg/pageView", this.node).getComponent(cc.PageView)
        pageView.node.on('page-turning', (pageView) => {
            Global.SlotsSoundMgr.playEffect("change");

            let pageIndex = pageView.getCurrentPageIndex()
            let unlockPage = self._roseStore.unlockPage
            self._page = pageIndex + 1
            self.updateUi()
            //商店上方spine
            if (this._page > unlockPage) {
                //到未解锁页面
                BigDuel_Tools.playSpineAni(this._upSpine, "animation" + (this._page + 4), false)
            } else {
                //到已解锁页面
                BigDuel_Tools.playSpineAni(this._upSpine, "animation" + this._page, false)
            }
            self.scheduleOnce(() => {
                Global.SlotsSoundMgr.playEffect("dialog_store_show");
            }, 0.2)
        });
    },

    onEnable() {
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    onDisable() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this);
    },

    updateData(roseStore) {
        this._roseStore = roseStore
        //拥有的玫瑰数量
        let haveRose = cc.find("bg/haveRoseBg/num", this.node)
        BigDuel_Tools.changeNodeLab(haveRose, Global.FormatNumToComma(this._roseStore.roseCnt))
        //检查是否是repick
        if (this._roseStore.repick == true) {
            this._repick = true
        }
    },

    initUi() {
        //当前已解锁页面
        this._upSpine.getComponent(sp.Skeleton).setAnimation(0, "animation" + this._page, false)
        //init item
        let pageDetails = this._roseStore.pageDetails

        let cloneItem = cc.find("bg/pageView/view/content/page_1/item", this.node)
        cloneItem.active = false
        let posArr = [cc.v2(-175, 150), cc.v2(0, 150), cc.v2(175, 150), cc.v2(-175, 0), cc.v2(0, 0), cc.v2(175, 0), cc.v2(-175, -150), cc.v2(0, -150), cc.v2(175, -150)]
        for (let i = 1; i < 6; i++) {
            let pageItem = cc.find("bg/pageView/view/content/page_" + i, this.node)
            let price = pageDetails[i - 1].price

            for (let j = 0; j < 9; j++) {
                let item = cc.instantiate(cloneItem)
                item.name = 'item' + j;
                item.active = true;
                item.setPosition(posArr[j])
                pageItem.addChild(item)
                item.getChildByName("coin").active = false
                item.getChildByName("spine").active = false
                item.price = price
                if (i < (this._roseStore.unlockPage + 1)) {
                    //可解锁页面
                    item.getChildByName("lock").active = false
                    BigDuel_Tools.changeNodeSp(item.getChildByName("itemBg"), this.itemCloseSpf)
                } else {
                    //未解锁页面
                    item.getChildByName("lock").active = true
                    BigDuel_Tools.changeNodeSp(item.getChildByName("itemBg"), this.itemGraySpf)
                }
                BigDuel_Tools.changeNodeLab(cc.find("price/lab", item), Global.formatNumShort(price))
                //解锁袋子
                Global.btnClickEvent(item, function () {
                    //判断价格
                    if (item.hasUnlock == true) return;//已打开
                    if (this._page > this._roseStore.unlockPage) return;//不能打开
                    if (this._roseStore.roseCnt < item.price && (!this._repick)) {
                        //钱不够
                        let tip = cc.instantiate(this._cannotOpenTip)
                        item.addChild(tip)
                        cc.tween(tip)
                            .call(() => {
                                tip.active = true
                                tip.y = 50
                                Global.SlotsSoundMgr.playEffect("tip");
                                BigDuel_Tools.nodeAni(tip, 1)
                            })
                            .delay(1)
                            .call(() => {
                                tip.removeFromParent()
                            })
                            .start()
                        return
                    };

                    Global.SlotsSoundMgr.playEffect("buy1");
                    // 发送51消息
                    let req = { c: MsgId.SLOT_SUBGAME_DATA };
                    req.gameid = cc.vv.gameData.getGameId()
                    req.data = {}
                    req.data.rtype = 2
                    req.data.pageId = i
                    req.data.choiceId = j + 1
                    cc.vv.NetManager.send(req, true);
                    this.repick(false)
                    //防止快速开启多个袋子
                    cc.find("bg/zheZhao", this.node).active = true
                }, this)

            }
        }

        //已解锁
        let unlockItems = this._roseStore.unlockItems
        for (let i = 1; i < (this._roseStore.unlockPage + 1); i++) {
            let pageItem = cc.find("bg/pageView/view/content/page_" + i, this.node)
            let unlockInfo = unlockItems[i - 1]
            for (const key in unlockInfo) {
                const itemInfo = unlockInfo[key];
                let item = pageItem.getChildByName('item' + (itemInfo.idx - 1))
                item.getChildByName("lock").active = false
                item.getChildByName("price").active = false
                item.getChildByName("itemBg").active = false

                let spineNode = item.getChildByName("spine")
                spineNode.active = true
                let spineCom = spineNode.getComponent(sp.Skeleton)
                if (itemInfo.type === 1) {
                    spineCom.setAnimation(0, "animation3_1", false)
                } else if (itemInfo.type === 2) {
                    //中金币
                    item.getChildByName("coin").active = true
                    spineCom.setAnimation(0, "animation1_1", false)
                    let showCoinNum = parseInt(itemInfo.coin / 1000) * 1000//取整k数
                    BigDuel_Tools.changeNodeLab(item.getChildByName("coin"), Global.formatNumShort(showCoinNum, 0))
                    //中双倍
                } else if (itemInfo.type === 3) {
                    //中bonus
                    spineCom.setAnimation(0, "animation2_1", false)
                }
                item.hasUnlock = true
                BigDuel_Tools.changeNodeSp(item.getChildByName("itemBg"), this.itemOpenSpf)
            }
        }

    },

    updateUi() {
        //拥有的玫瑰数量
        let bg = this.node.getChildByName('bg')
        let haveRose = cc.find("haveRoseBg/num", bg)
        BigDuel_Tools.changeNodeLab(haveRose, Global.FormatNumToComma(this._roseStore.roseCnt))
        //下方当前选择页choosebtn 显示
        let downNode = cc.find("bg/down", this.node)
        for (let i = 1; i < 6; i++) {
            let key = cc.find("chooseBtn" + i, downNode)
            BigDuel_Tools.changeNodeSp(key, this.chooseSpf1)
            if (i === this._page) {
                BigDuel_Tools.changeNodeSp(key, this.chooseSpf2)
            }
        }
    },

    //解锁item 回调
    async onRcvSubGameAction(msg) {
        if (msg.code != 200) return;
        let data = msg.data;
        let pageItem = cc.find("bg/pageView/view/content/page_" + data.pageId, this.node)
        let item = pageItem.getChildByName('item' + (data.choiceId - 1))
        let gameData = cc.vv.gameData;

        //有错误信息
        if (data.errMsg) {
            return
        }
        //及时更新主界面玫瑰数量
        let rose = cc.find("Canvas/safe_node/slots/reels_frame/frameUp/rose")
        let numLab = cc.find("numBg/num", rose)
        cc.vv.gameData.GetSlotsScript()._roseNum = data.roseStore.roseCnt
        BigDuel_Tools.changeNodeLab(numLab, Global.FormatNumToComma(data.roseStore.roseCnt))
        //检查是否是repick
        if (this._roseStore.repick == true) {
            this._repick = true
        }
        //刷新roseStore信息
        if (data.roseStore) {
            this.updateData(data.roseStore)
            this.updateUi()
        }

        //解锁item
        item.getChildByName("lock").active = false
        item.getChildByName("price").active = false
        item.getChildByName("itemBg").active = false
        item.hasUnlock = true
        item.stopAllActions()

        BigDuel_Tools.changeNodeSp(item.getChildByName("itemBg"), this.itemOpenSpf)
        let spineNode = item.getChildByName("spine")
        spineNode.active = true
        let spineCom = spineNode.getComponent(sp.Skeleton)
        //animation 1 中金币 2 双倍中奖 3 bonus免费游戏  4 x2动画  5 慢闪金光动画 等待  animation1_1 袋子打开 animation2_1 2倍 animation3_1 bonus游戏 
        //type FreeGame = 1,  -- 触发免费 Coin = 2,  -- 直接奖励物品  Repick = 3,  -- 再来一次，并翻倍
        switch (data.result.type) {
            case 1:
                //奖励免费游戏
                spineCom.setAnimation(0, "animation3", false)
                Global.SlotsSoundMgr.playEffect("buy2");
                gameData.SetSmallStoreToFreeGame(true)

                await this.awaitTime(1)
                spineCom.setAnimation(0, "animation3_1", false)
                BigDuel_Tools.nodeAni(this.node, 2)
                gameData.GetSlotsScript().delayFunc(() => {
                    cc.vv.gameData.GetSlotsScript().CheckEnterFreeGame(2)
                }, 1)
                break;
            case 2:
                //奖励金币
                spineCom.setAnimation(0, "animation1", false)
                await this.awaitTime(0.5)
                item.getChildByName("coin").active = true
                let coinNum = data.result.coin
                if (this._repick == true) {
                    coinNum = data.result.coin / 2
                }
                BigDuel_Tools.changeNodeLab(item.getChildByName("coin"), Global.formatNumShort(coinNum, 0))
                await this.awaitTime(0.5)
                spineCom.setAnimation(0, "animation1_1", false)

                this.repick(false)
                if (this._beginFlyItem) {
                    await this.flyliziAct(this._beginFlyItem, item)
                }
                BigDuel_Tools.changeNodeLab(item.getChildByName("coin"), Global.formatNumShort(data.result.coin, 0))

                //显示中奖的金币
                let haveWin = cc.vv.gameData.GetBottomScript().getCurrentWin()
                let addCoin = data.result.coin
                cc.vv.gameData.AddCoin(addCoin)
                // cc.vv.gameData.GetSlotsScript().ShowBottomWin(parseInt(addCoin), parseInt(haveWin + addCoin), true, null, 1)
                cc.vv.gameData.GetBottomScript().ShowWin(addCoin + haveWin, 3, haveWin, null, 0.3)
                cc.vv.gameData.GetTopScript().ShowCoin()
                break;
            case 3:
                //再来一次，并翻倍
                spineCom.setAnimation(0, "animation2", false)
                Global.SlotsSoundMgr.playEffect("buy3");
                await this.awaitTime(1)
                spineCom.setAnimation(0, "animation2_1", false)
                this._beginFlyItem = item;
                this.repick(true)
                break;
            default:
                break;
        }
        //防止快速开启多个袋子
        cc.find("bg/zheZhao", this.node).active = false
        //解锁单页
        if (data.result.pageReward) {
            this.goPageReward(data.pageId, data.result.pageReward);
        }

        this.checkCanOpen()
    },

    //检查当前拥有玫瑰数量是否可以开启新袋子
    checkCanOpen() {
        let pageItem = cc.find("bg/pageView/view/content/page_" + this._roseStore.unlockPage, this.node)
        let roseCnt = this._roseStore.roseCnt
        for (let i = 0; i < 9; i++) {
            let item = pageItem.getChildByName("item" + i)
            if (item.hasUnlock == true) continue;
            let price = item.price
            let spineNode = item.getChildByName("spine")
            if (roseCnt >= price) {
                spineNode.active = true

                BigDuel_Tools.changeNodeSp(item.getChildByName("itemBg"), this.itemCloseSpf)
                //流光动画
                if (item.getActionByTag(1) == null) {
                    cc.tween(item)
                        .delay(2 + i * 4)
                        .call(() => {
                            BigDuel_Tools.playSpineAni(spineNode, "animation5", false)
                        })
                        .union()
                        .repeatForever()
                        .tag(1)
                        .start()
                }
            } else {
                spineNode.active = false
                item.stopAllActions()
                BigDuel_Tools.changeNodeSp(item.getChildByName("itemBg"), this.itemGraySpf)
            }
        }
    },

    //飞粒子
    async flyliziAct(beginNode, endNode) {
        let self = this
        let flyLizi = cc.instantiate(this._flyLizi)
        flyLizi.parent = beginNode
        flyLizi.active = true
        flyLizi.setPosition(cc.v2(0, 0))
        let endPos = BigDuel_Tools.convetOtherNodeSpace(endNode, beginNode)
        cc.tween(flyLizi)
            .to(0.5, { position: endPos })
            .call(() => {
                flyLizi.removeFromParent()
                self._beginFlyItem = null;
                self._repick = false;
            })
            .start()
        this.awaitTime(1)
    },

    //中了repick  免费选择一次  isIn : true 进 fasle 出
    repick(isIn) {
        if (!this._roseStore.repick) return
        let unlockPage = this._roseStore.unlockPage
        let pageItem = cc.find("bg/pageView/view/content/page_" + unlockPage, this.node)
        for (let j = 0; j < 9; j++) {
            let item = pageItem.getChildByName("item" + j)
            if (!item.hasUnlock) {
                item.getChildByName("price").active = !isIn
            }
        }
    },

    //开启单页 免费游戏
    async goPageReward(pageId, pageReward) {
        Global.SlotsSoundMgr.playEffect("full")
        //框动画
        let spineNode1 = cc.find("kuangzhu", this.node)
        let spineNode2 = cc.find("quanpingqingzhu", this.node)
        spineNode1.active = true
        spineNode2.active = true
        spineNode1.getComponent(sp.Skeleton).setAnimation(0, "animation", false)
        spineNode2.getComponent(sp.Skeleton).setAnimation(0, "animation", false)

        //处于开启单页玫瑰商店进的免费游戏
        cc.vv.gameData.SetBigStoreToFreeGame(true)

        await this.awaitTime(2)
        await this.closeRoseStore()
        cc.vv.gameData.GetPopNodeScript().roseStoreToFreeGame(pageId, pageReward)

        //解锁下一页所有袋子
        let unlockPage = this._roseStore.unlockPage
        let pageItem = cc.find("bg/pageView/view/content/page_" + unlockPage, this.node)
        for (let j = 0; j < 9; j++) {
            let item = pageItem.getChildByName('item' + j)
            item.getChildByName("lock").active = false
            BigDuel_Tools.changeNodeSp(item.getChildByName("itemBg"), this.itemCloseSpf)
        }

    },

    //移动页面 1 左移动 2 右移动
    async movePage(type) {
        Global.SlotsSoundMgr.playEffect("change");
        let pageView = cc.find("bg/pageView", this.node).getComponent(cc.PageView)
        let unlockPage = this._roseStore.unlockPage
        let pageIndex = pageView.getCurrentPageIndex()
        let movePageIndex = 1

        //shandian kai  animation 1-5  6：1 7：2 8：3 9：4

        if (type === 1) {
            movePageIndex = pageIndex - 1
            if (movePageIndex === -1) movePageIndex = 4;

        } else if (type === 2) {
            movePageIndex = pageIndex + 1
            if (movePageIndex === 5) movePageIndex = 0;

        }
        this._page = movePageIndex + 1
        pageView.scrollToPage(movePageIndex)
        this.updateUi()
        //商店上方spine
        if (this._page > unlockPage) {
            //到未解锁页面
            BigDuel_Tools.playSpineAni(this._upSpine, "animation" + (this._page + 4), false)
        } else {
            //到已解锁页面
            BigDuel_Tools.playSpineAni(this._upSpine, "animation" + this._page, false)
        }
        this.scheduleOnce(() => {
            Global.SlotsSoundMgr.playEffect("dialog_store_show");
        }, 0.2)
    },

    //打开玫瑰商店
    showRoseStore() {
        BigDuel_Tools.nodeAni(this.node, 1)
        this.checkCanOpen()
        //防止快速开启多个袋子
        cc.find("bg/zheZhao", this.node).active = false
    },

    //关闭玫瑰商店
    closeRoseStore() {
        BigDuel_Tools.nodeAni(this.node, 2)
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },
});
