/**蒙面英雄-符号表 
 * 
*/
let BigDuel_Tools = require('./BigDuel_Tools')
let maskHeight = 106
let maskWidth = 124

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {

    },
    //重写
    StartMove: function () {
        this._super()
    },

    SetRoseText: function (num) {
        let roseSpine = cc.find("roseSpine", this.node)
        let roseFlyLizi = cc.find("roseFlyLizi", this.node)


        let rose = cc.find("Canvas/safe_node/slots/reels_frame/frameUp/rose")
        let targetPos = BigDuel_Tools.convetOtherNodeSpace(roseSpine, rose)

        let cloneRoseSpine = cc.instantiate(roseSpine)
        cloneRoseSpine.setPosition(targetPos)
        cloneRoseSpine.parent = rose
        let cloneRoseFlyLizi = cc.instantiate(roseFlyLizi)
        cloneRoseFlyLizi.setPosition(targetPos)
        cloneRoseFlyLizi.parent = rose

        let aniName1 = 'animation' + num / 5 + '_1'
        let aniName2 = 'animation' + num / 5 + '_2'

        cloneRoseSpine.active = true

        cloneRoseSpine.getComponent(sp.Skeleton).setAnimation(0, aniName2, false)
        cc.tween(cloneRoseSpine)
            .delay(0.3)
            .call(() => {
                cloneRoseSpine.getComponent(sp.Skeleton).setAnimation(0, aniName1, false)
            })
            .delay(0.1)
            .to(0.4, { position: cc.v2(0, 0) })
            .call(() => {
                cloneRoseSpine.removeFromParent()
            }).start()

        cc.tween(cloneRoseFlyLizi)
            .delay(0.5)
            .call(() => {
                cloneRoseFlyLizi.active = true
            })
            .to(0.4, { position: cc.v2(0, 0) })
            .start()

    },

    //重写 恢复到保存的状态
    Resume(backup) {
        if (!backup) return;
        this._symbolIdx = backup.symbolIdx;
        this._id = backup.id;
        this._data = Global.copy(backup.data);
        this.ShowKuang(backup.isKuang);
        this.ShowNormal();
        let state = backup.state;
        if (state == "win") {
            this.playWinAnimation();
        } else if (state == "stop") {
            this.playStopAnimation();
        } else if (state == "idle") {
            this.playidleAnimation();
        } else if (state == "trigger") {
            this.playTriggerAnimation(true);
        }
    },

    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playTriggerAnimation(bPlay) {
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (bPlay) {

            if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani) {
                this._state = "trigger";
                if (this._showNode) {
                    this._showNode.active = false
                }
                let aniNode = this.setAnimationToTop(true)
                aniNode.active = true
                let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
                topShowNode.active = true
                if (cfg.symbol[id].trigger_ani.name != "") {
                    aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                    isPlay = true
                    let nodeSp = topShowNode.getComponent(sp.Skeleton)
                    if (nodeSp) {
                        nodeSp.setAnimation(0, cfg.symbol[id].trigger_ani.name, true)
                    }
                }
            }
        } else {
            this.setAnimationToTop(false);
        }

        return isPlay
    },

});
