
cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    onLoad() {
        this._super();

        let safe_node = cc.find('safe_node', this.node)
        let cfg = cc.vv.gameData.getGameCfg()

        cc.vv.gameData.SetSlotsNode(cc.vv.gameData.GetSlotsScript().node)

        //wheel node
        let node_wheel = cc.find('wheel_node', safe_node)
        let script_wheel = node_wheel.getComponent("BigDuel_Wheel")
        script_wheel.Init()
        cc.vv.gameData.SetWheelScript(script_wheel)

        //node pop ui
        let node_pop = cc.find('node_pop_ui', safe_node)
        let script_pop = node_pop.getComponent("BigDuel_Pop")
        script_pop.Init()
        cc.vv.gameData.SetPopNodeScript(script_pop)

        //store 玫瑰商店src
        let node_store = cc.find('node_store', safe_node)
        let script_store = node_store.getComponent("BigDuel_Store")
        script_store.Init()
        cc.vv.gameData.SetStoreScript(script_store)
    },

});
