
/**蒙面英雄轮盘
 * 
*/
let BigDuel_Tools = require('./BigDuel_Tools')

cc.Class({
    extends: cc.Component,

    properties: {
        //cc
        _node_win: cc.node,//中sp 大奖显示node
        _node_wheel: cc.node,//转盘node
        _yuan_di: cc.node,//用于旋转的圆底
        _point_node: cc.node,//指向node

        _spine_moon: cc.node,//升级spine

        _wheelAtlas: null,//转盘用到图片plist

        //属性
        _bonusGameInfo: null,//服务器下发 bounus游戏信息
        _pointType: null,//指示器类型
        _gameTimes: 1,//游戏次数根据bonusGame.result数组长度来
    },

    async Init() {
        this._node_win = cc.find("node_win", this.node)
        this._spine_moon = cc.find("spine_moon", this.node)

        //转盘分为40等份
        this._node_wheel = cc.find("node_wheel", this.node)
        this._yuan_di = cc.find("yuanDi", this._node_wheel)
        this._point_node = cc.find("pointNode", this._node_wheel)

        this._wheelAtlas = cc.vv.gameData.GetAtlasByName('wheel')
        //item mult 倍数 respin 再来一次  jackpotId jp类型

        let collectBtn = cc.find("sureBtn", this._node_win)
        Global.btnClickEvent(collectBtn, async function () {
            collectBtn.stopAllActions();
            // collectBtn.getComponent(cc.Button).interactable = false
            Global.SlotsSoundMgr.playEffect("popup_out")
            BigDuel_Tools.nodeAni(this._node_win, 3)
            this.scheduleOnce(() => {
                // collectBtn.getComponent(cc.Button).interactable = true
                this.exitWheelGame()
            }, 0.6)
        }, this)
    },

    //进入游戏
    async enterWheelGame() {

        this._bonusGameInfo = cc.vv.gameData.GetSlotsScript()._gameInfo.bonusGame
        if (!this._bonusGameInfo) return

        this._pointType = this._bonusGameInfo.size
        this._gameTimes = this._bonusGameInfo.result.length;
        this.updateUi()
    },

    async updateUi() {

        this.node.active = true
        let _left_heiDi = cc.find("leftHeiDi", this._node_wheel)
        let _right_heiDi = cc.find("rightHeiDi", this._node_wheel)

        this._spine_moon.active = false;
        this._node_win.active = false;
        this._yuan_di.angle = 0

        //指示器动画
        let spine1_Point_node = this._node_wheel.getChildByName("pointSpine1")
        let spine2_Point_node = this._node_wheel.getChildByName("pointSpine2")
        spine1_Point_node.active = false
        spine2_Point_node.active = false
        //转盘颜色
        BigDuel_Tools.changeNodeSp(this._yuan_di, this._wheelAtlas.getSpriteFrame('yuanDi' + this._bonusGameInfo.wheelJackpot))
        //换遮罩
        BigDuel_Tools.changeNodeSp(_left_heiDi, this._wheelAtlas.getSpriteFrame('zz' + this._pointType))
        BigDuel_Tools.changeNodeSp(_right_heiDi, this._wheelAtlas.getSpriteFrame('zz' + this._pointType))
        //指示器
        BigDuel_Tools.changeNodeSp(this._point_node, this._wheelAtlas.getSpriteFrame('point' + this._pointType))
        //jackPot 对应的图片
        let jackPotArr = { 1: "mini", 2: "minor", 3: "maxi", 4: "major", 5: "grand", }

        if (this._yuan_di.childrenCount < 10) {
            for (let index = 0; index < 40; index++) {
                let item = cc.instantiate(cc.find("item", this._yuan_di))
                let itemInfo = this._bonusGameInfo.wheelItems[index]
                item.active = true
                item.name = "item" + index;
                item.angle = index * 9;
                item.parent = this._yuan_di;
                item.getChildByName("png1").active = false
                item.getChildByName("png2").active = false
                item.getChildByName("lab").active = false
                // item.getChildByName("txt").getComponent(cc.Label).string = index
                if (itemInfo.mult) {
                    //金币
                    item.getChildByName("lab").active = true
                    let coin = cc.vv.gameData.GetTotalBet() * itemInfo.mult
                    BigDuel_Tools.changeNodeLab(item.getChildByName("lab"), Global.FormatNumToComma(coin))
                }

                if (itemInfo.respin) {
                    //升级 也就是再来一次
                    BigDuel_Tools.changeNodeSp(item.getChildByName("png1"), this._wheelAtlas.getSpriteFrame('again' + itemInfo.respin))
                    item.getChildByName("png1").active = true
                }

                if (itemInfo.jackpotId) {
                    //中jp
                    BigDuel_Tools.changeNodeSp(item.getChildByName("png2"), this._wheelAtlas.getSpriteFrame(jackPotArr[itemInfo.jackpotId]))
                    item.getChildByName("png2").active = true
                }
            }
        }

        //圆底初始角度
        let offsetNumArr = { 1: 0, 2: -4.5, 3: -9, 4: -13.5 }
        this._yuan_di.angle = offsetNumArr[this._pointType]

        await this.awaitTime(1.5)
        //转第一次
        this.moveWheel(0)
    },

    //para：index 第几次游戏
    async moveWheel(index) {
        let self = this
        let itemArr = this._bonusGameInfo.result[index]
        //转盘转动音效
        Global.SlotsSoundMgr.playEffect("wheel_spin")
        //指示器动画
        this._node_wheel.getChildByName("pointSpine1").active = false
        this._node_wheel.getChildByName("pointSpine2").active = false

        let min = Math.min.apply(null, itemArr);
        let max = Math.max.apply(null, itemArr);
        let rightIndex = min
        //如果result里面有40 和1 同时存在 （跨界情况）
        if (BigDuel_Tools.numInArr(1, 40, itemArr)) {
            max = max - 1 //处理lua下标
            rightIndex = max

        } else {
            min = min - 1 //处理lua下标
            rightIndex = min
        }
        let targetRotation = -(rightIndex * 9) - 360 * 5;
        let spine1_Point_node = this._node_wheel.getChildByName("pointSpine1")
        let spine2_Point_node = this._node_wheel.getChildByName("pointSpine2")

        spine1_Point_node.active = true
        spine1_Point_node.getComponent(sp.Skeleton).setAnimation(0, "animation" + this._pointType, true)
        this._yuan_di.runAction(cc.rotateBy(8, targetRotation))

        await this.awaitTime(3)
        spine1_Point_node.getComponent(sp.Skeleton).setAnimation(0, "animation" + self._pointType + "_1", true)
        await this.awaitTime(5)
        //转盘停止音效
        Global.SlotsSoundMgr.playEffect("wheel_win")

        spine1_Point_node.active = false
        spine2_Point_node.active = true
        spine2_Point_node.getComponent(sp.Skeleton).setAnimation(0, "animation" + self._pointType, false)
        await this.awaitTime(0.8)
        spine2_Point_node.active = false

        //中的item动画
        this.playItemAni(itemArr, true)
        Global.SlotsSoundMgr.playEffect("wheel_win");

        await this.awaitTime(2)
        //显示中奖的金币
        let haveWin = cc.vv.gameData.GetBottomScript().getCurrentWin()
        // let addCoin = this._bonusGameInfo.winCoin
        let addCoin = this.getCoinByIndex(index)
        // cc.vv.gameData.AddCoin(addCoin)


        //升级动画
        if (this._gameTimes > (index + 1)) {
            await cc.vv.gameData.GetSlotsScript().ShowBottomWin(addCoin, haveWin + addCoin, false, null, 1)

            //item动画取消
            this.playItemAni(itemArr, false)
            //升级转场spine
            Global.SlotsSoundMgr.playEffect("transitionyun")
            this._spine_moon.active = true;
            this._spine_moon.getComponent(sp.Skeleton).setAnimation(0, "animation", false)
            //恢复圆盘
            let offsetNumArr = { 1: 0, 2: -4.5, 3: -9, 4: -13.5 }
            this._yuan_di.angle = offsetNumArr[this._pointType]
            await this.awaitTime(1.5)
            this._spine_moon.active = false;

            this.moveWheel(index + 1)
        } else {
            //检查是否中了jp
            await cc.vv.gameData.GetSlotsScript().ShowBottomWin(addCoin, haveWin + addCoin, true, null, 1)
            if (this._bonusGameInfo.jackpot && this._bonusGameInfo.jackpot.id) {
                this.showJpAni()
            } else {
                this.exitWheelGame()
            }
        }
    },

    //根据轮数index得到当轮wheel游戏中奖的金币
    getCoinByIndex(index) {
        let itemArr = this._bonusGameInfo.result[index]
        let wheelItems = this._bonusGameInfo.wheelItems
        let totalCoin = 0
        for (const key in itemArr) {
            const element = itemArr[key];
            let itemInfo = wheelItems[element - 1]
            if (itemInfo.mult) {
                let coin = cc.vv.gameData.GetTotalBet() * itemInfo.mult
                totalCoin = totalCoin + coin
            }
        }
        return totalCoin
    },

    //中jp大奖显示
    async showJpAni() {
        let jackpot = this._bonusGameInfo.jackpot.id
        let sureBtn = cc.find("sureBtn", this._node_win)
        let winCoinNode = cc.find("winCoinNode", this._node_win)

        Global.SlotsSoundMgr.playEffect("dialog_jp_collect")
        sureBtn.active = false
        winCoinNode.active = false
        this._node_win.active = true
        let aniName = { 1: 5, 2: 4, 3: 3, 4: 2, 5: 1 }
        cc.find("jptanchuang", this._node_win).getComponent(sp.Skeleton).setAnimation(0, "animation" + aniName[jackpot], false)
        cc.tween(this.node)
            .delay(0.5)
            .call(() => {
                sureBtn.active = true
                winCoinNode.active = true
                //金币数值框spine
                BigDuel_Tools.playSpineAni(cc.find("shuzikuang", winCoinNode))

                sureBtn.getChildByName("anniu").getComponent(sp.Skeleton).setAnimation(0, "animation", true)
                cc.find("numBg/num", winCoinNode).getComponent(cc.Label).string = Global.FormatNumToComma(this._bonusGameInfo.winCoin)
            })
            .delay(0.5)
            .call(() => {
                cc.find("jptanchuang", this._node_win).getComponent(sp.Skeleton).setAnimation(0, "animation" + aniName[jackpot] + "_1", true)
            })
            .start()

        await cc.vv.gameData.awaitTime(0.5);
        cc.vv.gameData.checkAutoPlay(sureBtn, ()=>{
            Global.SlotsSoundMgr.playEffect("popup_out")
            BigDuel_Tools.nodeAni(this._node_win, 3)
            this.scheduleOnce(() => {
                // collectBtn.getComponent(cc.Button).interactable = true
                this.exitWheelGame()
            }, 0.6)
        })
    },

    //播放item动画
    playItemAni(itemArr, isPlay) {
        for (const key in itemArr) {
            const element = itemArr[key];
            let itemInfo = this._bonusGameInfo.wheelItems[element - 1]
            let item = this._yuan_di.getChildByName("item" + (element - 1))
            let spineNode;
            let aniName = 'animation'
            if (itemInfo.mult) {
                //金币
                spineNode = item.getChildByName("lab").getChildByName("spineNode")
            }
            if (itemInfo.respin) {
                //再来一次
                spineNode = item.getChildByName("png1").getChildByName("spineNode")
                let nameArr = { 1: "animation_lv", 2: "animation_lam", 3: "animation_zi", 4: "animation_hong", 5: "animation_huang", }
                aniName = nameArr[itemInfo.respin]
            }
            if (itemInfo.jackpotId) {
                //再来一次
                spineNode = item.getChildByName("png2").getChildByName("spineNode")
                let nameArr = { 1: "animation_lv", 2: "animation_lan", 3: "animation_zi", 4: "animation_hong", 5: "animation_huang", }
                aniName = nameArr[itemInfo.jackpotId]
            }

            if (isPlay) {
                spineNode.active = true
                spineNode.getComponent(sp.Skeleton).setAnimation(0, aniName, true)
            } else {
                spineNode.getComponent(sp.Skeleton).clearTracks()
                spineNode.active = false
            }
        }
    },
    //退出转盘游戏
    exitWheelGame() {
        let self = this;
        cc.tween(this._node_wheel)
            .by(0.5, { y: -100, opacity: 0 })
            .call(() => {
                self.node.active = false
                self._node_wheel.y = -480
                self._node_wheel.opacity = 255

                //清除所有item
                for (let index = 0; index < 40; index++) {
                    let item = cc.find("item" + index, this._yuan_di)
                    if (item) {
                        item.removeFromParent()
                    }
                }
                cc.vv.gameData.GetSlotsScript().ExitBonusGame()
            })
            .start()

    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },
});
