
cc.Class({
    extends: cc.Component,

    properties: {

    },

    start() {

    },

    statics: {

        //切换节点的 SpriteFrame
        changeNodeSp(node, sp) {
            if (node == null) {
                return;
            }
            node.getComponent(cc.Sprite).spriteFrame = sp;
        },

        //切换节点的 label
        changeNodeLab(node, str) {
            if (node == null) {
                return;
            }
            node.getComponent(cc.Label).string = str;
        },

        //判断某两个个数在js数组中
        numInArr(num1, num2, arr) {
            let judge1 = arr.indexOf(num1)
            let judge2 = arr.indexOf(num2)
            if ((judge1 != -1) && (judge2 != -1)) {
                return true
            } else {
                return false
            }
        },

        //ui节点打开关闭 action 1 open 2 close 3 close
        nodeAni(node, type) {
            if (type === 1) {
                node.scale = 0
                node.active = true
                cc.tween(node)
                    .to(0.2, { scale: 1 })
                    .start()
            } else if (type === 2) {
                cc.tween(node)
                    .to(0.2, { scale: 0 })
                    .call(() => {
                        node.active = false
                        node.scale = 1
                    })
                    .start()
            } else if (type === 3) {
                cc.tween(node)
                    .to(0.2, { scale: 1.3 })
                    .to(0.3, { scale: 0 })
                    .call(() => {
                        node.active = false
                        node.scale = 1
                    })
                    .start()
            }

        },

        //spine节点播放动画
        playSpineAni(node, aniName = "animation", isloop = true, idx = 0) {
            if (node) {
                node.active = true
                let spine = node.getComponent(sp.Skeleton)
                spine.setAnimation(idx, aniName, isloop)
            }
        },

        //返回整k数
        getKNum(num) {
            if (num) {
                let backNum = parseInt(num / 1000) * 1000//取整k数
                return backNum
            }
        },

        //spine动画播放结束事件
        spineEndFunc(spineNode, callFunc){
            if(spineNode){
                spineNode.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    if(callFunc){
                        callFunc();
                    }
                })
            }

        },
        /**
         * 得到一个节点的世界坐标
         * node的原点在左下边
         * @param {*} node 
         */
        localConvertWorldPoint(node) {
            if (node) {
                return node.convertToWorldSpaceAR(cc.v2(0, 0));
            }
            return null;
        },

        /**
         * 把一个世界坐标的点，转换到某个节点下的坐标
         * 原点在node左下角
         * @param {*} node 
         * @param {*} worldPoint 
         */
        worldConvertLocalPoint(node, worldPoint) {
            if (node) {
                return node.convertToNodeSpace(worldPoint);
            }
            return null;
        },

        /**
         *  * 把一个节点的本地坐标转到另一个节点的本地坐标下
         * @param {*} node 
         * @param {*} targetNode 
         */
        convetOtherNodeSpace(node, targetNode) {
            if (!node || !targetNode) {
                return null;
            }
            //先转成世界坐标
            let worldPoint = this.localConvertWorldPoint(node);
            return this.worldConvertLocalPoint(targetNode, worldPoint);
        },


    }
    // update (dt) {},
});
