let BigDuel_Tools = require('./BigDuel_Tools')
/**
 * 蒙面英雄slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        // cc
        _entranceBtn: cc.node,//玫瑰商店入口
        _roseBtn: cc.node,//玫瑰商店入口

        //属性
        _roseNum: 0,//拥有的玫瑰花数量
    },


    onLoad() {
        this._super();
        //玫瑰商店入口
        this._entranceBtn = cc.find("reels_frame/frameUp/rose/entrance", this.node)
        Global.btnClickEvent(this._entranceBtn, function () {
            Global.SlotsSoundMgr.playEffect("dialog_store_show");
            this._bottomScript.ShowBtnsByState("moveing_1")
            cc.vv.gameData.GetStoreScript().showRoseStore()
        }, this)
        this._roseBtn = cc.find("reels_frame/frameUp/rose/roseBtn", this.node)
        Global.btnClickEvent(this._roseBtn, function () {
            Global.SlotsSoundMgr.playEffect("dialog_store_show");
            this._bottomScript.ShowBtnsByState("moveing_1")
            cc.vv.gameData.GetStoreScript().showRoseStore()
        }, this)

        this.playZuoluoAni()

        //监听下注
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, this.onEventTotalbetUpdated, this)

    },

    //重写
    StartMove: function () {
        this._super()
        //BGM
        Global.SlotsSoundMgr.playNormalBgm()
        //游戏开始不能进玫瑰商店
        this._entranceBtn.getComponent(cc.Button).interactable = false;
        this._roseBtn.getComponent(cc.Button).interactable = false;

    },

    //收到旋转结果
    //gameData模块收到数据后，转发到此处
    onMsgSpine: function (msg) {
        this._gameInfo = msg
        let cards = msg.resultCards
        this.SetSlotsResult(cards)
        this.SetReelStateInfo(cards)
        cc.vv.gameData.GetStoreScript().updateData(msg.roseStore)
    },

    //重写：显示bonus中奖
    OnSpinEnd: function () {
        this.onSpinEndAction();
    },

    async onSpinEndAction() {
        //显示中奖路线
        this.ShowWinTrace()
        //显示收集玫瑰
        this.collectRose()
        //显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        //减一下bonus游戏的钱
        if (this._gameInfo.bonusGame && this._gameInfo.bonusGame.winCoin) {
            nWin -= this._gameInfo.bonusGame.winCoin
        }
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }

        await new Promise((sucess, failed) => {
            let isUpdate = true
            if (this._gameInfo.bonusGame) {
                isUpdate = false
            }
            this.ShowBottomWin(nWin, nTotal, isUpdate, function () {
                sucess()
            });
        });

        if (this._gameInfo.freeResult.freeInfo.freeCnt) {
            //免费游戏中又中免费游戏
            await this.enterDoubleFreeGame()
        } else if (this._gameInfo.bonusGame) {
            // 获得转盘游戏
            await this.CheckTriggerSubGame();
        } else if (this._gameInfo.allFreeCnt > 0 && this._gameInfo.freeCnt == 0) {
            // 结束免费游戏
            await this.CheckExitFreeGame();
        } else if (this._gameInfo.freeGameOptions) {
            // 获得免费游戏 以freeGameOptions为开启免费游戏标准
            await this.CheckEnterFreeGame(1);
        } else {
            this.CanDoNextRound()
        }

        //游戏结束可以进玫瑰商店
        let rest = cc.vv.gameData.GetFreeTime()
        let autoTime = cc.vv.gameData.GetAutoModelTime()
        if (rest == 0 && autoTime <= 0) {
            //免费游戏和自动模式不开启玫瑰商店
            this._entranceBtn.getComponent(cc.Button).interactable = true;
            this._roseBtn.getComponent(cc.Button).interactable = true;
        }

    },

    //重写 触发bonus轮盘游戏
    async CheckTriggerSubGame() {
        //所有的SYMBOL停止显示动画
        this.stopAllSymbolAni()

        //播放bonus图标动画
        for (let id of this._gameInfo.bonusGame.idxs) {
            let symbol = this.GetSymbolByIdx(id)
            if (symbol) {
                symbol.playTriggerAnimation(true)
            }
        }
        //symbpl_bonus音效
        Global.SlotsSoundMgr.playEffect("symbol_bonus");
        await this.awaitTime(1);

        Global.SlotsSoundMgr.playEffect("trigger");

        await this.awaitTime(1.5);
        for (let id of this._gameInfo.bonusGame.idxs) {
            let symbol = this.GetSymbolByIdx(id)
            if (symbol) {
                symbol.playTriggerAnimation(false)
            }
        }
        Global.SlotsSoundMgr.playEffect("transitionmoon");

        await this.playZuoluoAni(true)
        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("bonus_bgm");

        //卷轴移动下去
        let reels_bg = cc.find("reels_bg", this.node)
        let reels = cc.find("reels", this.node)
        let reels_frame = cc.find("reels_frame", this.node)
        let top_ani = cc.find("top_ani", this.node)
        reels_bg.runAction(cc.moveTo(0.8, cc.v2(0, -800)))
        reels.runAction(cc.moveTo(0.8, cc.v2(0, -800)))
        reels_frame.runAction(cc.moveTo(0.8, cc.v2(0, -800)))
        top_ani.runAction(cc.moveTo(0.8, cc.v2(0, -960)))

        cc.vv.gameData.GetPopNodeScript().showWheelGame()
    },

    // 退出bonus游戏
    async ExitBonusGame() {
        //卷轴移动上去
        let reels_bg = cc.find("reels_bg", this.node)
        let reels = cc.find("reels", this.node)
        let reels_frame = cc.find("reels_frame", this.node)
        let top_ani = cc.find("top_ani", this.node)

        reels_bg.runAction(cc.moveTo(0.8, cc.v2(0, 0)))
        reels.runAction(cc.moveTo(0.8, cc.v2(0, 0)))
        reels_frame.runAction(cc.moveTo(0.8, cc.v2(0, 0)))
        top_ani.runAction(cc.moveTo(0.8, cc.v2(0, -180)))

        //播放bonus图标动画
        for (let id of this._gameInfo.bonusGame.idxs) {
            let symbol = this.GetSymbolByIdx(id)
            if (symbol) {
                symbol.playTriggerAnimation(true)
            }
        }

        await this.awaitTime(2);
        Global.SlotsSoundMgr.playNormalBgm();
        this.CanDoNextRound();
    },

    //检查是否触发免费 type 1 中卷轴进免费 2玫瑰商店进免费游戏 
    async CheckEnterFreeGame(type) {
        Global.SlotsSoundMgr.stopBgm();
        let popNodeSrc = cc.vv.gameData.GetPopNodeScript()

        if (type == 1) {
            for (let id of this._gameInfo.freeGameOptions.scatterIdx) {
                let symbol = this.GetSymbolByIdx(id)
                if (symbol) {
                    symbol.playTriggerAnimation(true)
                }
            }

            Global.SlotsSoundMgr.playEffect("bell");
            //保存symbol状态
            this.Backup();
            await this.awaitTime(4)
            // 转场动画播放中 停掉scatter图标动画
            for (let id of this._gameInfo.freeGameOptions.scatterIdx) {
                let symbol = this.GetSymbolByIdx(id)
                if (symbol) {
                    symbol.playTriggerAnimation(false)
                }
            }
        } else {
            this.Backup();
        }

        //进入免费游戏选择界面
        Global.SlotsSoundMgr.playEffect("dialog_sfg_start");
        popNodeSrc.showFreeGame()
    },

    //免费游戏中又进免费
    async enterDoubleFreeGame() {
        Global.SlotsSoundMgr.playEffect("transitionz");
        for (let id of this._gameInfo.freeResult.freeInfo.scatterIdx) {
            let symbol = this.GetSymbolByIdx(id)
            if (symbol) {
                symbol.playTriggerAnimation(true)
            }
        }

        await this.awaitTime(1.5);
        await cc.vv.gameData.GetPopNodeScript().showFreeGameDialog(2, this._gameInfo.freeResult.freeInfo.freeCnt);

        for (let id of this._gameInfo.freeResult.freeInfo.scatterIdx) {
            let symbol = this.GetSymbolByIdx(id)
            if (symbol) {
                symbol.playTriggerAnimation(false)
            }
        }

        this.CanDoNextRound()
    },

    //重写
    ReconnectShow: function () {
        let GameData = cc.vv.gameData
        let deskInfo = GameData._deskInfo
        //免费是否选择了
        if (deskInfo.freeGameOptions) {
            //未选择免费次数选项
            this._bottomScript.ShowBtnsByState("moveing_1")
            GameData.GetPopNodeScript().showFreeGame()
        }
        else {
            let total = GameData.GetTotalFree()
            let rest = GameData.GetFreeTime()
            if (rest > 0) {
                Global.SlotsSoundMgr.playBgm('free_bgm')

                //已经处于免费游戏中
                this._bottomScript.ShowFreeModel(true, total - rest, total)
                let nTotal = GameData.GetTotalFreeWin()
                this._bottomScript.SetWin(nTotal)
                //增加行数
                this.extendLine(deskInfo.freeGameInfo.row, 0.01)

                this.CanDoNextRound()
                this.ShowGameview(true)
            }
        }
        //update 玫瑰商店的信息
        GameData.GetStoreScript().updateData(deskInfo.roseStore)
        //玫瑰花显示
        this._roseNum = deskInfo.roseStore.roseCnt
        //解锁bonus游戏条件
        GameData.SetJackpotUnlock(deskInfo.JackpotUnlock)
        this.onEventTotalbetUpdated()

        //更新玫瑰数量
        let num = cc.find("reels_frame/frameUp/rose/numBg/num", this.node)
        BigDuel_Tools.changeNodeLab(num, Global.FormatNumToComma(Math.floor(deskInfo.roseStore.roseCnt)))

    },

    //重写：退出免费游戏
    async CheckExitFreeGame() {
        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playEffect("dialog_sfg_collect");

        if (cc.vv.gameData.GetBigStoreToFreeGame()) {
            //开启单页玫瑰商店的免费游戏退出
            cc.vv.gameData.GetPopNodeScript().exitStoreFreeGame(this._gameInfo.freeWinCoin);
        } else {
            await cc.vv.gameData.GetPopNodeScript().showFreeGameDialog(3, this._gameInfo.freeWinCoin);
        }
    },

    //收集玫瑰花
    async collectRose() {
        let roseInfo = this._gameInfo.roseInfo;
        if (!roseInfo || roseInfo.totalCnt === 0) return;

        Global.SlotsSoundMgr.playEffect("collect_rose");
        for (let i = 0; i < roseInfo.idxs.length; i++) {
            let symbol = this.GetSymbolByIdx(roseInfo.idxs[i])
            if (symbol) {
                let src = symbol.getComponent("BigDuel_symbol")
                src.SetRoseText(roseInfo.cnts[i])
            }
        }
        await this.awaitTime(0.7)

        //总数
        let rose = cc.find("reels_frame/frameUp/rose", this.node)
        let bigRose = cc.find("reels_frame/frameUp/bigRose", this.node)
        let numLab = cc.find("numBg/num", rose)

        rose.getComponent(sp.Skeleton).setAnimation(0, "animation2", false)

        if (bigRose.active) {
            //5x8卷轴是展示大玫瑰花
            BigDuel_Tools.changeNodeLab(cc.find("numBg/num", rose), Global.FormatNumToComma(Math.floor(this._roseNum + roseInfo.totalCnt)))
            numLab = cc.find("numBg/num", bigRose)
        }
        Global.doRoallNumEff(numLab, this._roseNum, this._roseNum + roseInfo.totalCnt, 0.5, null, null, 0, true);
        this._roseNum += roseInfo.totalCnt;

        await this.awaitTime(0.5)

        rose.getComponent(sp.Skeleton).setAnimation(0, "animation1", true)
    },

    //扩展列的行数 立即生效(用于免费游戏中)  count行数 time 时间 
    extendLine(count, time = 0.01) {
        let GameCfg = cc.vv.gameData.getGameCfg()
        let addLineNum = count - GameCfg.row
        GameCfg.row = count
        //修改topaniNode的高度
        let topAniNode = cc.find("Canvas/safe_node/slots/top_ani")
        topAniNode.height = count * GameCfg.symbolSize.height
        if (addLineNum > 0) {
            for (let i = 0; i < 5; i++) {
                this._reels[i].AddCount(addLineNum, time)
            }
        }

        this._row = this._cfg.row
    },

    //恢复列的行数 （退出免费游戏）
    recoverLine(time = 0.01) {
        let data1 = cc.vv.gameData.getGameCfg().row
        let data2 = cc.vv.gameData.getGameCfg().realRow
        let addLineNum = data2 - data1
        //修改topaniNode的高度
        let topAniNode = cc.find("Canvas/safe_node/slots/top_ani")
        topAniNode.height = data2 * 93
        //恢复卷轴
        if (addLineNum != 0) {
            for (let i = 0; i < 5; i++) {
                this._reels[i].AddCount(addLineNum, time)
            }
        }
        //隐藏掉多余列的中奖动画
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let symbol4 = item._symbols[4]
            symbol4.setAnimationToTop(false)
            symbol4.ShowKuang(false)

        }
        //恢复卷轴正常行数
        cc.vv.gameData.getGameCfg().row = cc.vv.gameData.getGameCfg().realRow;
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    async ShowGameview(bFree) {
        if (bFree) {
            Global.SlotsSoundMgr.playBgm('free_bgm')

            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()
            this._bottomScript.ShowFreeModel(true, total - rest, total)

            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            this._bottomScript.SetWin(nTotal)
            cc.find("reels_frame/frameUp/rose", this.node).y = 110
            cc.find("reels_frame/frameUp/unLockNode", this.node).active = false

            //免费游戏不开启玫瑰商店
            this._entranceBtn.getComponent(cc.Button).interactable = false;
            this._roseBtn.getComponent(cc.Button).interactable = false;
        }
        else {
            this._bottomScript.ShowFreeModel(false)
            cc.find("reels_frame/frameUp/rose", this.node).y = 160
            cc.find("reels_frame/frameUp/unLockNode", this.node).active = true
            //免费游戏不开启玫瑰商店
            this._entranceBtn.getComponent(cc.Button).interactable = true;
            this._roseBtn.getComponent(cc.Button).interactable = true;
        }

        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        if (normalBg) {
            normalBg.active = !bFree
        }
        if (normalFree) {
            normalFree.active = bFree
        }
    },

    //佐罗动画播放 isInBonus:是否是进bonus游戏
    async playZuoluoAni(isInBonus) {
        //佐罗spine animation 1普通 2小动 3中动 "animation"bonus游戏转场
        let spine_role = cc.find("new_role", this.node)
        if (isInBonus) {
            spine_role.stopAllActions()
            spine_role.getComponent(sp.Skeleton).setAnimation(0, "skill", false)
            await this.awaitTime(2);
        }
        spine_role.getComponent(sp.Skeleton).setAnimation(0, "idle", true)

    },

    //下注update
    onEventTotalbetUpdated(data, bInit) {
        let GameData = cc.vv.gameData
        let _bet = 0;

        if (data) {
            _bet = data.detail;
        }

        let unLockNode = cc.find("reels_frame/frameUp/unLockNode", this.node)
        let betMultsArr = GameData.GetBetMults()//押注列表 钱
        let _JackpotUnlock = GameData.GetJackpotUnlock() //解锁bonus index数组
        let betIndex = cc.vv.gameData.GetBetIdx()//当前押注index
        let nodeArr = [cc.find("Mini", unLockNode), cc.find("Minor", unLockNode), cc.find("Maxi", unLockNode), cc.find("Major", unLockNode), cc.find("Grand", unLockNode)]
        for (let i = 0; i < 5; i++) {
            let isUnLock = false //是否解锁
            let lockNum = 0//解锁需要的钱
            if (betIndex >= _JackpotUnlock[i]) {
                isUnLock = true
            }
            if (betMultsArr[_JackpotUnlock[i] - 1]) {
                lockNum = betMultsArr[_JackpotUnlock[i] - 1]
            } else {
                lockNum = betMultsArr[betMultsArr.length - 1] * (i + 2)
            }
            this.changLockBonusItem(nodeArr[i], isUnLock, lockNum)
        }

    },

    changLockBonusItem(node, isUnLock, lockNum) {
        let spineNode = cc.find("spine", node) //animation 解锁 animation3 关闭 animation2图片

        let txt = spineNode.getChildByName("num").getComponent(cc.Label)
        txt.string = Global.formatNumShort(lockNum, 0);

        if (isUnLock) {
            //解锁
            if (node.isUnLock === true) return
            node.isUnLock = true
            node.stopAllActions()
            cc.tween(node)
                .call(() => {
                    spineNode.getChildByName("num").active = false
                    BigDuel_Tools.playSpineAni(spineNode, "animation", false)
                })
                .delay(1)
                .call(() => {
                    spineNode.active = false
                })
                .start()

        } else {
            //未解锁
            if (node.isUnLock === false) return
            node.isUnLock = false

            node.stopAllActions()
            cc.tween(node)
                .call(() => {
                    spineNode.active = true
                    BigDuel_Tools.playSpineAni(spineNode, "animation3", false)

                })
                .delay(1)
                .call(() => {
                    spineNode.getChildByName("num").active = true
                    BigDuel_Tools.playSpineAni(spineNode, "animation2", false)
                })
                .start()

        }
    },

    //停止所有的symbol动画
    stopAllSymbolAni() {
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            for (let i = 0; i < item._symbols.length; i++) {
                let element = item._symbols[i];
                element.ShowNormal();
                element.ShowKuang(false)
            }
        }
    },

    //延迟调用
    delayFunc(func, time) {
        this.scheduleOnce(() => {
            func()
        }, time)
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },
});
